#!/usr/bin/env bash
# Generated by CH57x Config Editor
set -euo pipefail
cd "$(dirname "$0")"
TOOL='./it'\''s-tool'
cat > mapping.yaml <<'CH57X_YAML_EOF'
# Generated by CH57x Config Editor
model: ch57x-2
orientation: normal
rows: 3
columns: 4
knobs: 2
layers:
  - buttons:
      - ["a", "ctrl-a", "alt-shift", "alt-ctrl,ctrl-b"]
      - ["e", "f", "g", "h"]
      - ["<100>", "j", "k", "l"]
    knobs:
      - ccw: "wheelup"
        press: "click"
        cw: "wheeldown"
      - ccw: "shift-wheelup"
        press: "shift-click"
        cw: "shift-wheeldown"

  - buttons:
      - ["click", "click(middle)", "click+rclick", "ctrl-mclick"]
      - ["move(0,10)", "alt-drag(right,10,0)", "ctrl-move(5,5)", "ctrl-wheelup"]
      - ["alt-wheel(1)", "ctrl-click", "wheelup", "wheelup"]
    knobs:
      - ccw: "left"
        press: "enter"
        cw: "right"
      - ccw: "ctrl-left"
        press: "ctrl-enter"
        cw: "ctrl-right"

  - buttons:
      - ["play", "prev", "next", "mute"]
      - ["2", "3", "4", "5"]
      - ["6", "7", "8", "9"]
    knobs:
      - ccw: "volumedown"
        press: "mute"
        cw: "volumeup"
      - ccw: "d"
        press: "e"
        cw: "f"
CH57X_YAML_EOF
"$TOOL" validate mapping.yaml
"$TOOL" upload mapping.yaml
echo Uploaded.
